.cocreatesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2e25;
    background: linear-gradient(160deg, #f1f7ef 0%, #e6f1ea 100%);
    border-radius: 18px;
}

.cocreatesim-container * {
    box-sizing: border-box;
}

.cocreatesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #16513a 0%, #1f7a52 55%, #3aa66f 100%);
    color: #f3fbf6;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(22, 81, 58, 0.30);
}

.cocreatesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.cocreatesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #cdeedb;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.cocreatesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e0f3e8;
}

.cocreatesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #1d5f43;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.cocreatesim-period-counter #currentDay,
.cocreatesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #16513a;
}

.cocreatesim-round-name {
    background: #d2ecdd;
    color: #16513a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cocreatesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3b12;
    background: #fbe8dc;
    padding: 4px 12px;
    border-radius: 999px;
}

.cocreatesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cocreatesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6e8dc;
    box-shadow: 0 4px 14px rgba(22, 81, 58, 0.06);
    border-top: 4px solid #3aa66f;
}

.cocreatesim-card-value { border-top-color: #1f7a52; }
.cocreatesim-card-destruct { border-top-color: #c0392b; }
.cocreatesim-card-nps { border-top-color: #2f86b0; }
.cocreatesim-card-margin { border-top-color: #c9881a; }

.cocreatesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5d7a6c;
}

.cocreatesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #16513a;
}

.cocreatesim-card-value .cocreatesim-value { color: #1f7a52; }
.cocreatesim-card-destruct .cocreatesim-value { color: #c0392b; }
.cocreatesim-card-nps .cocreatesim-value { color: #2f86b0; }
.cocreatesim-card-margin .cocreatesim-value { color: #c9881a; }

.cocreatesim-sublabel {
    font-size: 0.76rem;
    color: #6f8c7d;
    line-height: 1.35;
}

/* state highlights */
.cocreatesim-destruct-low .cocreatesim-value { color: #1f7a52; }
.cocreatesim-destruct-high .cocreatesim-value { color: #c0392b; }
.cocreatesim-margin-breach { border-top-color: #c0392b; }
.cocreatesim-margin-breach .cocreatesim-value { color: #c0392b; }

.cocreatesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16513a;
    color: #eafaf1;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.cocreatesim-budget-bar.cocreatesim-budget-over {
    background: #8a2417;
}

.cocreatesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.cocreatesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #3aa66f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(22, 81, 58, 0.05);
}

.cocreatesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cocreatesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #16513a;
    margin-bottom: 6px;
}

.cocreatesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c463a;
}

.cocreatesim-briefing-text strong { color: #1f7a52; }
.cocreatesim-briefing-text em { color: #9a3b12; font-style: italic; }

.cocreatesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6e8dc;
    box-shadow: 0 4px 14px rgba(22, 81, 58, 0.06);
}

.cocreatesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #16513a;
    border-bottom: 2px solid #e2f0e8;
    padding-bottom: 8px;
}

.cocreatesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #214a39;
    margin: 14px 0 6px;
}

.cocreatesim-container select,
.cocreatesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b6d6c4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6fbf8;
    color: #1c2e25;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cocreatesim-container select:focus,
.cocreatesim-container input[type="number"]:focus {
    outline: none;
    border-color: #1f7a52;
    box-shadow: 0 0 0 3px rgba(31, 122, 82, 0.15);
}

.cocreatesim-container select option {
    background-color: #ffffff;
    color: #1c2e25;
}

.cocreatesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f7a52;
}

.cocreatesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1d5f43;
    margin-top: 4px;
}

.cocreatesim-range-readout span:last-child {
    color: #c9881a;
    font-weight: 800;
}

.cocreatesim-hint {
    font-size: 0.8rem;
    color: #6f8c7d;
    margin-top: 4px;
    line-height: 1.4;
}

.cocreatesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cocreatesim-container .btn-primary {
    background: linear-gradient(135deg, #1f7a52 0%, #3aa66f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 122, 82, 0.28);
}

.cocreatesim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.cocreatesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #b6d6c4;
    color: #5d7a6c;
}

.cocreatesim-coach {
    background: #16513a;
    color: #eafaf1;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(22, 81, 58, 0.22);
}

.cocreatesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fd4ad;
    margin-bottom: 8px;
}

.cocreatesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cocreatesim-coach-body strong { color: #ffe09a; }
.cocreatesim-coach-body em { color: #ffc1ad; font-style: italic; }

.cocreatesim-history,
.cocreatesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6e8dc;
    box-shadow: 0 4px 14px rgba(22, 81, 58, 0.06);
}

.cocreatesim-history h3,
.cocreatesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #16513a;
}

.cocreatesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #214a39;
}

.cocreatesim-container table#usfHistoryTable th {
    background: #e7f3ec;
    color: #16513a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d2e8db;
}

.cocreatesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef5f0;
}

.cocreatesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fbf9;
}

.cocreatesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cocreatesim-container {
        padding: 14px;
    }
    .cocreatesim-header h1 {
        font-size: 1.7rem;
    }
    .cocreatesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cocreatesim-value {
        font-size: 2rem;
    }
    .cocreatesim-clock {
        margin-left: 0;
    }
    .cocreatesim-period-counter {
        font-size: 0.88rem;
    }
    .cocreatesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cocreatesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion modal (dark-on-light for the framework's white modal) ===== */
.cocreatesim-cm { text-align: center; color: #1c2e25; padding: 8px 4px 4px; }
.cocreatesim-cm-title { font-size: 1.05rem; font-weight: 700; color: #16513a; margin-bottom: 10px; }
.cocreatesim-cm-scorewrap { margin: 4px 0 6px; }
.cocreatesim-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #1f7a52; }
.cocreatesim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5d7a6c; }
.cocreatesim-cm-scorelabel { font-size: .78rem; text-transform: uppercase; letter-spacing: .05em; color: #5d7a6c; }
.cocreatesim-cm-grade { font-size: 1.3rem; font-weight: 700; color: #1c2e25; margin: 6px 0; }
.cocreatesim-cm-badges { margin: 8px 0 12px; }
.cocreatesim-cm-badge { display: inline-block; padding: 5px 12px; border-radius: 999px; font-size: .82rem; font-weight: 700; }
.cocreatesim-cm-badge-ok { background: #d6f0e2; color: #14663f; border: 1px solid #1f7a52; }
.cocreatesim-cm-badge-fail { background: #f7d9d5; color: #8f2418; border: 1px solid #c0392b; }
.cocreatesim-cm-badge-warn { background: #fdf0d6; color: #8a5a12; border: 1px solid #d59a2c; }
.cocreatesim-cm-kpis { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; margin: 10px 0; }
.cocreatesim-cm-kpi { background: #f2f7f4; border: 1px solid #d9e6df; border-radius: 10px; padding: 10px 14px; min-width: 92px; }
.cocreatesim-cm-kpi-n { font-size: 1.5rem; font-weight: 800; color: #16513a; }
.cocreatesim-cm-kpi-l { font-size: .72rem; text-transform: uppercase; letter-spacing: .03em; color: #5d7a6c; }
.cocreatesim-cm-kpi-l span { display: block; text-transform: none; letter-spacing: 0; color: #8aa093; }
.cocreatesim-cm-insights { text-align: left; margin: 12px auto 2px; max-width: 560px; background: #f7faf8; border: 1px solid #e0ebe5; border-radius: 10px; padding: 10px 14px; }
.cocreatesim-cm-insights-h { font-weight: 700; color: #16513a; margin-bottom: 6px; font-size: .9rem; }
.cocreatesim-cm-insights ul { margin: 0; padding-left: 18px; }
.cocreatesim-cm-insights li { color: #2a3f36; font-size: .88rem; margin-bottom: 4px; }

