(function() {
    'use strict';

    class CoCreateAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Co-Creation or Co-Destruction`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_VALUE = 30;        // co-created value (low, headroom for 4 rounds)
            this.START_DESTRUCT = 58;     // co-destruction risk (high = bad)
            this.START_NPS = 34;          // satisfaction proxy, churn at 3.4%
            this.START_MARGIN = 34.0;     // contribution margin %
            this.MARGIN_FLOOR = 30.0;     // CFO non-negotiable
            this.BUDGET_CAP = 2000;       // €2.0M service-ops cap, in €k
            this.MARGIN_SWING = 4.0;      // full-cap spend (2000k) costs 4 margin points -> 30.0%

            // Success target for the debrief.
            this.VALUE_TARGET = 58;
        }

        // v1.1.0 — composite 0-100 the reporting layer reads. Formula identical
        // to getPerformanceSummary (kept in one place so they can never diverge).
        _composite(ds) {
            const value = Math.round(ds.value);
            const destruct = Math.round(ds.destruct);
            const nps = Math.round(ds.nps);
            return Math.max(0, Math.min(100, Math.round(value * 0.35 + (100 - destruct) * 0.35 + nps * 0.30)));
        }

        // v1.1.0 — safe i18n lookup with an English fallback (chart/legend chrome).
        _cl(key, fallback) {
            try {
                const s = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key) : key;
                return (s && s !== key) ? s : fallback;
            } catch (e) { return fallback; }
        }

        // Locale-aware EUR money: EN "€90k" / ES "90k €".
        _money(k) {
            const n = Math.round(Number(k) || 0);
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            return (lang === `es`) ? (n + `k €`) : (`€` + n + `k`);
        }

        _moneyCap(used) {
            const u = Math.round(Number(used) || 0);
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            return (lang === `es`)
                ? (u + `k € / 2.000k €`)
                : (`€` + u + `k / €2,000k`);
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    value: this.START_VALUE,
                    destruct: this.START_DESTRUCT,
                    nps: this.START_NPS,
                    margin: this.START_MARGIN,
                    budgetUsed: 0,
                    marginBreached: false,
                    capBreached: false,
                    valueHistory: [this.START_VALUE],
                    destructHistory: [this.START_DESTRUCT],
                    npsHistory: [this.START_NPS],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    worst: `onboarding`,
                    whose: `integration`,
                    diagnosis: 55,
                    onboard: `light`,
                    expectation: `honest`,
                    coaching: `usage`,
                    community: 120,
                    rule: `mutual`,
                    misuse: `designout`,
                    misuseSpend: 120,
                    signal: 55,
                    sequence: `reengage`,
                    friction: `easeguided`,
                    board: `interaction`,
                    conviction: 65
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const w = document.getElementById(`worstInput`);
                const wh = document.getElementById(`whoseInput`);
                const dg = document.getElementById(`diagnosisInput`);
                if (w) decisions.worst = w.value;
                if (wh) decisions.whose = wh.value;
                if (dg) decisions.diagnosis = parseInt(dg.value, 10);
                if (!Number.isFinite(decisions.diagnosis) || decisions.diagnosis < 0 || decisions.diagnosis > 100) {
                    warn(`warn_diagnosis_range`); return false;
                }
            } else if (round === 2) {
                const ob = document.getElementById(`onboardInput`);
                const ex = document.getElementById(`expectationInput`);
                const co = document.getElementById(`coachingInput`);
                const cm = document.getElementById(`communityInput`);
                if (ob) decisions.onboard = ob.value;
                if (ex) decisions.expectation = ex.value;
                if (co) decisions.coaching = co.value;
                if (cm) decisions.community = parseFloat(cm.value);
                if (!Number.isFinite(decisions.community) || decisions.community < 0) {
                    warn(`warn_community_range`); return false;
                }
            } else if (round === 3) {
                const ru = document.getElementById(`ruleInput`);
                const mi = document.getElementById(`misuseInput`);
                const ms = document.getElementById(`misuseSpendInput`);
                const sg = document.getElementById(`signalInput`);
                if (ru) decisions.rule = ru.value;
                if (mi) decisions.misuse = mi.value;
                if (ms) decisions.misuseSpend = parseFloat(ms.value);
                if (sg) decisions.signal = parseInt(sg.value, 10);
                if (!Number.isFinite(decisions.misuseSpend) || decisions.misuseSpend < 0) {
                    warn(`warn_misusespend_range`); return false;
                }
                if (!Number.isFinite(decisions.signal) || decisions.signal < 0 || decisions.signal > 100) {
                    warn(`warn_signal_range`); return false;
                }
            } else if (round === 4) {
                const sq = document.getElementById(`sequenceInput`);
                const fr = document.getElementById(`frictionInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sq) decisions.sequence = sq.value;
                if (fr) decisions.friction = fr.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // valueDelta = co-created value gained; destructDelta = change in co-destruction
            // (negative = good, we are reducing destruction); npsDelta = satisfaction change;
            // spend = €k charged against the cap (reduces margin).
            let valueDelta = 0, destructDelta = 0, npsDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Locate the two real co-destruction touchpoints; resist the marketing framing.
                if (d.worst === `onboarding` || d.worst === `coaching`) {
                    valueDelta += 12; destructDelta -= 10; coachKey = `coach_r1_touchpoint_right`;
                } else if (d.worst === `acquire`) {
                    valueDelta -= 6; destructDelta += 4; coachKey = `coach_r1_acquire`;
                } else {
                    valueDelta -= 8; destructDelta += 6; coachKey = `coach_r1_renewal`;
                }

                // Plé's lens: the FAILURE IS IN THE INTEGRATION (firm asked, customer never gave,
                // flow misread the household) — not "only the firm" or "only the customer".
                if (d.whose === `integration`) {
                    valueDelta += 12; destructDelta -= 10;
                    if (d.worst === `onboarding` || d.worst === `coaching`) coachKey = `coach_r1_diag_sharp`;
                } else if (d.whose === `firm` || d.whose === `customer`) {
                    valueDelta += 1; destructDelta -= 1; coachKey = `coach_r1_oneside`;
                } else {
                    valueDelta -= 10; destructDelta += 8; coachKey = `coach_r1_neither`;
                }

                // Framing churn as interaction design, not a discount/marketing problem.
                if (d.diagnosis >= 60) { valueDelta += 6; destructDelta -= 4; }
                else if (d.diagnosis <= 25) { valueDelta -= 6; destructDelta += 4; coachKey = `coach_r1_marketing`; }

                summaryKey = ((d.worst === `onboarding` || d.worst === `coaching`) && d.whose === `integration`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Redesign: integrate resources well WITHOUT piling on features/agents (subtraction).
                // Onboarding: light-touch wins (80% of data, 20% of friction); mandatory trades one
                // co-destruction point for another (drop-off); none leaves it broken.
                switch (d.onboard) {
                    case `light`: spend += 350; valueDelta += 14; destructDelta -= 12; npsDelta += 6; coachKey = `coach_r2_light`; break;
                    case `mandatory`: spend += 300; valueDelta += 4; destructDelta += 4; npsDelta -= 6; coachKey = `coach_r2_friction`; break;
                    case `none`: valueDelta -= 6; destructDelta += 4; coachKey = `coach_r2_noonboard`; break;
                }

                // Expectations: honest "comfort vs savings" kills the backlash; adding features is
                // Common Error 1 (more surface area for co-destruction + breaks the cap); silence keeps it.
                switch (d.expectation) {
                    case `honest`: spend += 150; valueDelta += 8; destructDelta -= 10; npsDelta += 10; coachKey = (d.onboard === `light`) ? `coach_r2_redesign` : coachKey; break;
                    case `more`: spend += 600; valueDelta -= 6; destructDelta += 12; npsDelta -= 6; coachKey = `coach_r2_morefeatures`; break;
                    case `silent`: valueDelta -= 2; destructDelta += 4; npsDelta -= 4; coachKey = `coach_r2_silent`; break;
                }

                // Coaching: usage-driven personalisation is the relevant fix; 60 human coaches blow the
                // cap (€1.6M); generic scripts keep the "preachy" co-destruction.
                switch (d.coaching) {
                    case `usage`: spend += 450; valueDelta += 12; destructDelta -= 10; npsDelta += 6; break;
                    case `agents`: spend += 1600; valueDelta += 8; destructDelta -= 4; npsDelta += 4; coachKey = `coach_r2_agents`; break;
                    case `generic`: spend += 50; valueDelta -= 2; destructDelta += 4; npsDelta -= 4; coachKey = `coach_r2_generic`; break;
                }

                // Peer community (third actor): curated co-creation is cheap value; un-curated invites misuse.
                spend += d.community;
                if (d.community >= 80) { valueDelta += 6; npsDelta += 3; destructDelta -= 2; }
                else if (d.community > 0) { valueDelta += 2; destructDelta += 6; coachKey = `coach_r2_uncurated`; }

                summaryKey = (d.onboard === `light` && d.expectation === `honest` && d.coaching === `usage`) ? `sum_r2_good`
                    : (d.expectation === `more` || d.coaching === `agents` ? `sum_r2_overbuilt` : `sum_r2_weak`);
            } else if (round === 3) {
                // Co-creation rule: mutual & easy to honour beats firm-does-all (re-opens over-promise)
                // or customer-must-prove (friction barrier).
                switch (d.rule) {
                    case `mutual`: valueDelta += 14; destructDelta -= 12; npsDelta += 6; coachKey = `coach_r3_mutual`; break;
                    case `firmheavy`: valueDelta -= 6; destructDelta += 10; npsDelta -= 4; coachKey = `coach_r3_firmheavy`; break;
                    case `customerheavy`: valueDelta -= 4; destructDelta += 8; npsDelta -= 6; coachKey = `coach_r3_customerheavy`; break;
                    case `none`: valueDelta -= 8; destructDelta += 6; coachKey = `coach_r3_norule`; break;
                }

                // Misuse: design it out / convert (durable) beats punitive (spreads co-destruction to
                // the loyal base) or ignore (the trick spreads).
                switch (d.misuse) {
                    case `designout`: valueDelta += 8; destructDelta -= 12; npsDelta += 4; coachKey = (d.rule === `mutual`) ? `coach_r3_designout` : coachKey; break;
                    case `convert`: valueDelta += 10; destructDelta -= 8; npsDelta += 6; break;
                    case `punitive`: valueDelta -= 6; destructDelta += 14; npsDelta -= 14; coachKey = `coach_r3_punitive`; break;
                    case `ignore`: valueDelta -= 4; destructDelta += 10; npsDelta -= 4; coachKey = `coach_r3_ignore`; break;
                }

                // Spend for the fix. Design-out/convert need real build effort; punitive is cheap.
                spend += d.misuseSpend;
                if ((d.misuse === `designout` || d.misuse === `convert`)) {
                    if (d.misuseSpend >= 80) { destructDelta -= 4; valueDelta += 3; }
                    else { destructDelta += 6; coachKey = `coach_r3_underfunded`; }
                }

                // Signal weighting: protecting the 236,000 loyal customers over chasing €88k.
                if (d.signal >= 60) { npsDelta += 6; destructDelta -= 4; }
                else if (d.signal <= 25) { npsDelta -= 6; destructDelta += 4; coachKey = (d.misuse === `punitive`) ? coachKey : `coach_r3_lowsignal`; }

                summaryKey = (d.rule === `mutual` && (d.misuse === `designout` || d.misuse === `convert`)) ? `sum_r3_good`
                    : (d.misuse === `punitive` ? `sum_r3_punitive` : `sum_r3_weak`);
            } else if (round === 4) {
                // Recovery sequencing against the 45-day cold snap.
                switch (d.sequence) {
                    case `reengage`: valueDelta += 12; destructDelta -= 10; npsDelta += 8; coachKey = `coach_r4_reengage`; break;
                    case `acquire`: valueDelta -= 4; destructDelta += 6; npsDelta -= 4; coachKey = `coach_r4_acquire`; break;
                    case `freeze`: valueDelta -= 8; destructDelta += 8; npsDelta -= 6; coachKey = `coach_r4_freeze`; break;
                }

                // Ease friction without re-opening the gap: progressive onboarding is the balance.
                switch (d.friction) {
                    case `easeguided`: valueDelta += 10; destructDelta -= 8; npsDelta += 6; break;
                    case `removeall`: valueDelta -= 6; destructDelta += 12; npsDelta += 2; coachKey = `coach_r4_removeall`; break;
                    case `forceharder`: valueDelta -= 4; destructDelta += 6; npsDelta -= 8; coachKey = `coach_r4_forceharder`; break;
                }

                // The board pitch: interaction redesign vs a marketing fix vs scrapping the guarantee.
                switch (d.board) {
                    case `interaction`: valueDelta += 10; destructDelta -= 8; npsDelta += 6; coachKey = (d.sequence === `reengage` && d.friction === `easeguided`) ? `coach_r4_board_strong` : coachKey; break;
                    case `discount`: valueDelta -= 8; destructDelta += 6; npsDelta += 2; coachKey = `coach_r4_discount`; break;
                    case `scrap`: valueDelta -= 4; destructDelta += 4; npsDelta -= 6; coachKey = `coach_r4_scrap`; break;
                }

                // Conviction nudges value.
                valueDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.sequence === `reengage` && d.friction === `easeguided` && d.board === `interaction`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // --- scale deltas so meters never peg before the final round ---
            // Keep relative ordering intact (correct stays strictly best) while preserving
            // headroom: the concept-best path climbs steadily to ~mid-80s value / ~low-teens
            // destruction by Round 4, so every wrong lever still registers through the end.
            valueDelta = valueDelta * 0.48;
            destructDelta = destructDelta * 0.48;
            npsDelta = npsDelta * 0.72;

            // --- apply deltas ---
            ds.value = Math.max(0, Math.min(100, ds.value + valueDelta));
            ds.destruct = Math.max(0, Math.min(100, ds.destruct + destructDelta));
            // Satisfaction tracks both value gained and destruction reduced.
            ds.nps = Math.max(0, Math.min(100, ds.nps + npsDelta));

            // --- resources & margin ---
            ds.budgetUsed = Math.round(ds.budgetUsed + spend);
            if (ds.budgetUsed > this.BUDGET_CAP) ds.capBreached = true;
            // Margin erodes with spend: full €2.0M cap = 4 points -> lands exactly at the 30% floor.
            ds.margin = Math.round((this.START_MARGIN - (ds.budgetUsed / this.BUDGET_CAP) * this.MARGIN_SWING) * 10) / 10;
            if (ds.margin < this.MARGIN_FLOOR - 0.05) {
                ds.marginBreached = true;
                // Breaching the floor (over-spend, e.g. the 60-coaches option) drags everything down.
                const breach = (this.MARGIN_FLOOR - ds.margin);
                ds.value = Math.max(0, ds.value - breach * 2);
                ds.nps = Math.max(0, ds.nps - breach * 2);
                ds.destruct = Math.min(100, ds.destruct + breach * 2);
                if (coachKey === `coach_default` || round === 2) coachKey = `coach_capbreach`;
            }

            ds.valueHistory.push(Math.round(ds.value));
            ds.destructHistory.push(Math.round(ds.destruct));
            ds.npsHistory.push(Math.round(ds.nps));

            // v1.1.0 FIX — persist the composite where the grading/reporting layer reads it
            // (express_resolveDomainScore -> domainState.performance.overallScore), every period,
            // so the instructor panel score and the per-round score trend both populate.
            const overallScore = this._composite(ds);
            ds.performance = { overallScore: overallScore };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                value: Math.round(ds.value),
                valueDelta: Math.round(valueDelta),
                destruct: Math.round(ds.destruct),
                destructDelta: Math.round(destructDelta),
                nps: Math.round(ds.nps),
                npsDelta: Math.round(npsDelta),
                margin: ds.margin,
                budgetUsed: ds.budgetUsed,
                marginBreached: ds.marginBreached,
                capBreached: ds.capBreached,
                score: overallScore,
                overallScore: overallScore,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

