        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const value = Math.round(ds.value);
            const destruct = Math.round(ds.destruct);
            const nps = Math.round(ds.nps);
            const margin = ds.margin;

            const hitValue = value >= this.VALUE_TARGET;
            const lowDestruct = destruct <= 28;
            const marginOk = margin >= this.MARGIN_FLOOR - 0.05 && !ds.capBreached;
            // Composite: value up, destruction down (inverted), satisfaction up.
            const composite = this._composite(ds);

            let gradeKey = `grade_persists`;
            if (hitValue && lowDestruct && marginOk && composite >= 70) gradeKey = `grade_cocreated`;
            else if (hitValue && lowDestruct && marginOk) gradeKey = `grade_ontrack`;
            else if (!marginOk) gradeKey = `grade_breached`;
            else if (value > this.START_VALUE + 15) gradeKey = `grade_fragile`;
            const performance = window.mySimulation.t(gradeKey);

            const insights = [];
            if (hitValue && lowDestruct && marginOk) insights.push(window.mySimulation.t(`insight_cocreated`));
            else if (!marginOk) insights.push(window.mySimulation.t(`insight_capbreach`));
            else if (destruct > 45) insights.push(window.mySimulation.t(`insight_destruct`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (nps < 40) insights.push(window.mySimulation.t(`insight_trust`));
            if (destruct <= 20) insights.push(window.mySimulation.t(`insight_designedout`));
            if (hitValue && lowDestruct && nps >= 60) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                value: value,
                destruct: destruct,
                nps: nps,
                margin: margin,
                hitValue: hitValue,
                marginOk: marginOk,
                composite: composite,
                performance: performance,
                gradeKey: gradeKey,
                passed: (hitValue && lowDestruct && marginOk),
                insights: insights
            };
        }

        // v1.1.0 FIX — real completion modal (score / localized grade / MET or
        // distinct-failure badge / KPI strip / insights). Replaces the framework's
        // generic "You completed N periods" fallback. Dark-on-light for the white modal.
        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k;
            const s = summary || {};
            const score = Number.isFinite(s.composite) ? s.composite : 0;
            const grade = s.performance || t(s.gradeKey || `grade_persists`);
            const passed = !!s.passed;
            const breached = (s.marginOk === false);
            const val = Math.round(s.value != null ? s.value : 0);
            const des = Math.round(s.destruct != null ? s.destruct : 0);
            const nps = Math.round(s.nps != null ? s.nps : 0);
            const mar = (s.margin != null) ? Number(s.margin).toFixed(1) : `—`;
            let badge;
            if (passed) {
                badge = `<span class="cocreatesim-cm-badge cocreatesim-cm-badge-ok">✓ ` + t(`cm_met`) + `</span>`;
            } else if (breached) {
                badge = `<span class="cocreatesim-cm-badge cocreatesim-cm-badge-fail">✕ ` + t(`cm_breach`) + `</span>`;
            } else {
                badge = `<span class="cocreatesim-cm-badge cocreatesim-cm-badge-warn">• ` + t(`cm_missed`) + `</span>`;
            }
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightHtml = insights.length
                ? `<div class="cocreatesim-cm-insights"><div class="cocreatesim-cm-insights-h">` + t(`cm_insights`) + `</div><ul>` + insights.map((x) => `<li>` + x + `</li>`).join(``) + `</ul></div>`
                : ``;
            return `
                <div class="cocreatesim-cm">
                    <div class="cocreatesim-cm-title">` + t(`cm_title`) + `</div>
                    <div class="cocreatesim-cm-scorewrap">
                        <div class="cocreatesim-cm-score">` + score + `<span class="cocreatesim-cm-score-max">/100</span></div>
                        <div class="cocreatesim-cm-scorelabel">` + t(`cm_score_of`) + `</div>
                    </div>
                    <div class="cocreatesim-cm-grade">` + grade + `</div>
                    <div class="cocreatesim-cm-badges">` + badge + `</div>
                    <div class="cocreatesim-cm-kpis">
                        <div class="cocreatesim-cm-kpi"><div class="cocreatesim-cm-kpi-n">` + val + `</div><div class="cocreatesim-cm-kpi-l">` + t(`cm_value`) + ` <span>` + t(`cm_target`) + `</span></div></div>
                        <div class="cocreatesim-cm-kpi"><div class="cocreatesim-cm-kpi-n">` + des + `</div><div class="cocreatesim-cm-kpi-l">` + t(`cm_destruct`) + `</div></div>
                        <div class="cocreatesim-cm-kpi"><div class="cocreatesim-cm-kpi-n">` + nps + `</div><div class="cocreatesim-cm-kpi-l">` + t(`cm_nps`) + `</div></div>
                        <div class="cocreatesim-cm-kpi"><div class="cocreatesim-cm-kpi-n">` + mar + `%</div><div class="cocreatesim-cm-kpi-l">` + t(`cm_margin`) + `</div></div>
                    </div>
                    ` + insightHtml + `
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.capBreached || ds.marginBreached) return window.mySimulation.t(`hint_cap`);
