            if (ds.nps < 30) return window.mySimulation.t(`hint_trust`);
            if (state.currentPeriod >= 3 && ds.value < 45) return window.mySimulation.t(`hint_behind`);
            if (ds.value >= this.VALUE_TARGET && ds.destruct <= 28) return window.mySimulation.t(`hint_strong`);
